using System.Collections.Concurrent;using System.Net;using System.Net.Http;using System.Net.Sockets;using System.Security.Authentication;using TownOfHost;
partial class Program {
const string ChatPrivate="DO-NOT-LOG-CHAT-URL-CREDENTIAL";
static void SafeChat(IEnumerable<YouTubeChatDiagnostic> events){foreach(var value in events){string s=value.SafeLog;foreach(var forbidden in new[]{ChatPrivate,"synthetic-credential","chat-id","resume-token",Video,"https://","Bearer","日本語😀"})Check(!s.Contains(forbidden),"diagnostic leaked private payload");Check(s.StartsWith("YOUTUBE_CHAT stage=")&&!s.Contains('\n')&&!s.Contains('\r'));}}
static (OfficialYouTubeChatSource Source,ApiHandler Handler,List<YouTubeChatDiagnostic> Events) DiagnosticApi(params HttpResponseMessage[] responses){var h=new ApiHandler();foreach(var response in responses)h.Responses.Enqueue(response);var events=new List<YouTubeChatDiagnostic>();return(new(new MemoryYouTubeCredentials(Credential()),new HttpClient(h),progress:events.Add),h,events);}
sealed class StageHandler:HttpMessageHandler {
 internal int Calls;internal bool StreamStage,Wait;internal Exception Error;
 protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Calls++;if(StreamStage&&Calls==1)return JsonReply(LiveJson());if(Wait)await Task.Delay(Timeout.Infinite,ct);throw Error??new HttpRequestException(ChatPrivate);}
}
sealed class ChatBrokenStream:MemoryStream {public override ValueTask<int> ReadAsync(Memory<byte> bytes,CancellationToken ct=default)=>new(Task.FromException<int>(new IOException(ChatPrivate)));}
sealed class SecondCredential:IYouTubeCredentialProvider {internal int Calls;public Task<YouTubeCredential> GetAsync(CancellationToken token)=>Task.FromResult(++Calls==1?Credential():new YouTubeCredential("synthetic-expired",false,DateTimeOffset.UtcNow.AddSeconds(-1)));}
static void RunChatDiagnostics(){
Test("diagnostic schema clamps numeric fields and unknown enums",()=>{var d=new YouTubeChatDiagnostic((YouTubeChatStage)999,(YouTubeChatCode)999,999,99,9,(YouTubeChatExceptionKind)999,(YouTubeChatExceptionKind)999,-1,long.MaxValue,99,-1,(YouTubeFailure)999);Check(d.SafeLog.Contains("stage=Unknown code=Unknown http=0 grpc=unknown httpMajor=0")&&d.SafeLog.Contains("elapsedMs=0 totalMs=86400000 attempt=4 retryDelaySec=0 reason=Unknown"));});
Test("all successful stages are visible before normal stream EOF",()=>{var(s,h,d)=DiagnosticApi(JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(Batch(Message(text:ChatPrivate)))));using(s)SourceRun(s).GetAwaiter().GetResult();foreach(var stage in new[]{YouTubeChatStage.Credential,YouTubeChatStage.VideosRequest,YouTubeChatStage.VideosResponse,YouTubeChatStage.ActiveLiveChatId,YouTubeChatStage.StreamRequest,YouTubeChatStage.StreamHeaders,YouTubeChatStage.GrpcStatus,YouTubeChatStage.Receive,YouTubeChatStage.Parse})Check(d.Any(x=>x.Stage==stage));Check(d.Any(x=>x.Code==YouTubeChatCode.Http2Established&&x.HttpStatus==200&&x.HttpMajor==2)&&d.Last().Code==YouTubeChatCode.EndOfStream&&d.Last().GrpcStatus==0);SafeChat(d);});
foreach(var c in new[]{(401,"",YouTubeFailure.AuthenticationExpired),(403,"forbidden",YouTubeFailure.PermissionDenied),(403,"quotaExceeded",YouTubeFailure.QuotaExceeded),(404,"",YouTubeFailure.NotFound),(429,"",YouTubeFailure.QuotaExceeded),(503,"",YouTubeFailure.NetworkInterrupted)})Test("videos HTTP rejection diagnostic "+c.Item1+c.Item2,()=>{string body="{\"private\":\""+ChatPrivate+"\",\"error\":{\"errors\":[{\"reason\":\""+c.Item2+"\"}]}}";var(s,h,d)=DiagnosticApi(JsonReply(body,(HttpStatusCode)c.Item1));using(s)Deny(c.Item3,()=>SourceRun(s).GetAwaiter().GetResult());Check(h.Requests.Count==1&&d.Last().Stage==YouTubeChatStage.VideosResponse&&d.Last().Code==YouTubeChatCode.HttpRejected&&d.Last().HttpStatus==c.Item1&&d.Last().Failure==c.Item3);SafeChat(d);});
foreach(var c in new[]{("\"actualEndTime\":\"2026-11-13T00:00:00Z\"",YouTubeFailure.LiveEnded),("\"actualStartTime\":\"2026-11-13T00:00:00Z\"",YouTubeFailure.ChatUnavailable),("",YouTubeFailure.NotLive)})Test("live chat ID condition diagnostic "+c.Item2,()=>{var(s,h,d)=DiagnosticApi(JsonReply(LiveJson(c.Item1)));using(s)Deny(c.Item2,()=>SourceRun(s).GetAwaiter().GetResult());Check(d.Last().Stage==YouTubeChatStage.ActiveLiveChatId&&d.Last().Failure==c.Item2&&h.Requests.Count==1);SafeChat(d);});
Test("invalid videos JSON reports lookup parser without body",()=>{var(s,h,d)=DiagnosticApi(JsonReply(ChatPrivate));using(s)Deny(YouTubeFailure.InvalidResponse,()=>SourceRun(s).GetAwaiter().GetResult());Check(d.Last().Stage==YouTubeChatStage.ActiveLiveChatId&&d.Last().Code==YouTubeChatCode.InvalidPayload);SafeChat(d);});
foreach(bool stream in new[]{false,true})foreach(var cause in new[]{YouTubeChatExceptionKind.Socket,YouTubeChatExceptionKind.TlsAuthentication,YouTubeChatExceptionKind.IO})Test("pre-mapping exception and nested cause "+stream+cause,()=>{Exception inner=cause==YouTubeChatExceptionKind.Socket?new SocketException((int)SocketError.HostNotFound):cause==YouTubeChatExceptionKind.TlsAuthentication?new AuthenticationException(ChatPrivate):new IOException(ChatPrivate);var h=new StageHandler{StreamStage=stream,Error=new HttpRequestException(ChatPrivate,inner)};var d=new List<YouTubeChatDiagnostic>();using var s=new OfficialYouTubeChatSource(new MemoryYouTubeCredentials(Credential()),new HttpClient(h),progress:d.Add);try{SourceRun(s).GetAwaiter().GetResult();throw new Exception("expected network failure");}catch(HttpRequestException){}Check(d.Last().Stage==(stream?YouTubeChatStage.StreamRequest:YouTubeChatStage.VideosRequest)&&d.Last().Code==YouTubeChatCode.NetworkFailure&&d.Last().ExceptionKind==YouTubeChatExceptionKind.HttpRequest&&d.Last().Cause==cause&&d.Last().HttpStatus==0&&(cause!=YouTubeChatExceptionKind.Socket||d.Last().SocketStatus==SocketError.HostNotFound));SafeChat(d);});
foreach(bool stream in new[]{false,true})Test("local deadline distinguished from user cancel "+stream,()=>{var h=new StageHandler{StreamStage=stream,Wait=true};var d=new List<YouTubeChatDiagnostic>();using var s=new OfficialYouTubeChatSource(new MemoryYouTubeCredentials(Credential()),new HttpClient(h),progress:d.Add,videoTimeout:TimeSpan.FromMilliseconds(50),headerTimeout:TimeSpan.FromMilliseconds(50));try{SourceRun(s).GetAwaiter().GetResult();throw new Exception("expected timeout");}catch(OperationCanceledException){}Check(d.Count(x=>x.Code==YouTubeChatCode.Timeout)==1&&d.Last().Stage==(stream?YouTubeChatStage.StreamRequest:YouTubeChatStage.VideosRequest)&&d.Last().ElapsedMs>=10&&d.Last().ExceptionKind==YouTubeChatExceptionKind.Cancellation);SafeChat(d);});
Test("videos response read IO records HTTP200 and response stage",()=>{var response=JsonReply("{}");response.Content=new StreamContent(new ChatBrokenStream());var(s,h,d)=DiagnosticApi(response);using(s){try{SourceRun(s).GetAwaiter().GetResult();throw new Exception("expected IO");}catch(IOException){}}Check(d.Last().Stage==YouTubeChatStage.VideosResponse&&d.Last().HttpStatus==200&&d.Last().ExceptionKind==YouTubeChatExceptionKind.IO);SafeChat(d);});
foreach(var c in new[]{(16,YouTubeFailure.AuthenticationExpired),(7,YouTubeFailure.PermissionDenied),(8,YouTubeFailure.QuotaExceeded),(9,YouTubeFailure.ChatUnavailable),(5,YouTubeFailure.NotFound),(14,YouTubeFailure.NetworkInterrupted),(3,YouTubeFailure.InvalidResponse)})Test("gRPC rejection numeric diagnostic "+c.Item1,()=>{var(s,h,d)=DiagnosticApi(JsonReply(LiveJson()),GrpcReply(Array.Empty<byte>(),c.Item1.ToString()));using(s)Deny(c.Item2,()=>SourceRun(s).GetAwaiter().GetResult());Check(d.Last().Stage==YouTubeChatStage.GrpcStatus&&d.Last().Code==YouTubeChatCode.GrpcRejected&&d.Last().GrpcStatus==c.Item1&&d.Last().HttpStatus==200&&d.Last().Failure==c.Item2);SafeChat(d);});
Test("trailers only error is distinguished before reading frames",()=>{var response=GrpcReply(Array.Empty<byte>(),null);response.Headers.Add("grpc-status","16");var(s,h,d)=DiagnosticApi(JsonReply(LiveJson()),response);using(s)Deny(YouTubeFailure.AuthenticationExpired,()=>SourceRun(s).GetAwaiter().GetResult());Check(d.Last().GrpcStatus==16&&!d.Any(x=>x.Stage==YouTubeChatStage.Receive));SafeChat(d);});
Test("missing trailers records unknown rather than success",()=>{var(s,h,d)=DiagnosticApi(JsonReply(LiveJson()),GrpcReply(Array.Empty<byte>(),null));using(s)Deny(YouTubeFailure.InvalidResponse,()=>SourceRun(s).GetAwaiter().GetResult());Check(d.Last().Code==YouTubeChatCode.MissingGrpcStatus&&d.Last().GrpcStatus==-1);SafeChat(d);});
foreach(bool version in new[]{false,true})Test("HTTP2 or media incompatibility diagnostic "+version,()=>{var response=GrpcReply(Array.Empty<byte>(),version:version?HttpVersion.Version11:HttpVersion.Version20);if(!version)response.Content.Headers.ContentType=new("text/plain");var(s,h,d)=DiagnosticApi(JsonReply(LiveJson()),response);using(s)Deny(YouTubeFailure.TransportUnsupported,()=>SourceRun(s).GetAwaiter().GetResult());Check(d.Last().Stage==YouTubeChatStage.StreamHeaders&&d.Last().Code==YouTubeChatCode.UnsupportedTransport&&!d.Any(x=>x.Code==YouTubeChatCode.Http2Established));SafeChat(d);});
Test("stream HTTP503 distinguished before gRPC status",()=>{var(s,h,d)=DiagnosticApi(JsonReply(LiveJson()),JsonReply(ChatPrivate,HttpStatusCode.ServiceUnavailable));using(s)Deny(YouTubeFailure.NetworkInterrupted,()=>SourceRun(s).GetAwaiter().GetResult());Check(d.Last().Stage==YouTubeChatStage.StreamHeaders&&d.Last().HttpStatus==503&&d.Last().GrpcStatus==-1);SafeChat(d);});
Test("frame read IO records receive stage",()=>{var response=GrpcReply(Array.Empty<byte>());response.Content=new StreamContent(new ChatBrokenStream());response.Content.Headers.ContentType=new("application/grpc");var(s,h,d)=DiagnosticApi(JsonReply(LiveJson()),response);using(s){try{SourceRun(s).GetAwaiter().GetResult();throw new Exception("expected IO");}catch(IOException){}}Check(d.Last().Stage==YouTubeChatStage.Receive&&d.Last().ExceptionKind==YouTubeChatExceptionKind.IO);SafeChat(d);});
Test("late malformed protobuf is logged after first successful frame",()=>{var frames=Proto(YouTubeGrpcProtocol.Frame(Batch(Message(text:ChatPrivate))),YouTubeGrpcProtocol.Frame(new byte[]{0}));var(s,h,d)=DiagnosticApi(JsonReply(LiveJson()),GrpcReply(frames));using(s)Deny(YouTubeFailure.InvalidResponse,()=>SourceRun(s).GetAwaiter().GetResult());Check(d.Any(x=>x.Stage==YouTubeChatStage.Parse&&x.Code==YouTubeChatCode.Completed)&&d.Last().Stage==YouTubeChatStage.Parse&&d.Last().Code==YouTubeChatCode.InvalidPayload);SafeChat(d);});
Test("success diagnostics remain bounded for two hundred frames",()=>{byte[] data=Proto(Enumerable.Range(0,200).Select(_=>YouTubeGrpcProtocol.Frame(Batch(Message(text:ChatPrivate)))).ToArray());var(s,h,d)=DiagnosticApi(JsonReply(LiveJson()),GrpcReply(data));using(s)SourceRun(s).GetAwaiter().GetResult();Check(d.Count<=24&&d.Count(x=>x.Stage==YouTubeChatStage.Parse&&x.Code==YouTubeChatCode.Completed)==1);SafeChat(d);});
Test("planned call renewal is not a diagnostic timeout failure",()=>{var response=GrpcReply(Array.Empty<byte>());response.Content=new StreamContent(new NeverReadStream());response.Content.Headers.ContentType=new("application/grpc");var h=new ApiHandler();h.Responses.Enqueue(JsonReply(LiveJson()));h.Responses.Enqueue(response);var d=new List<YouTubeChatDiagnostic>();using var s=new OfficialYouTubeChatSource(new MemoryYouTubeCredentials(Credential()),new HttpClient(h),TimeSpan.FromMilliseconds(80),d.Add);SourceRun(s).GetAwaiter().GetResult();Check(d.Last().Code==YouTubeChatCode.Renewal&&!d.Any(x=>x.Code==YouTubeChatCode.Timeout));SafeChat(d);});
Test("caller cancellation remains cancellation with no reconnect",()=>{var response=GrpcReply(Array.Empty<byte>());response.Content=new StreamContent(new NeverReadStream());response.Content.Headers.ContentType=new("application/grpc");var(s,h,d)=DiagnosticApi(JsonReply(LiveJson()),response);using(s){using var cancel=new CancellationTokenSource(50);try{SourceRun(s,token:cancel.Token).GetAwaiter().GetResult();throw new Exception("expected cancellation");}catch(OperationCanceledException){}}Check(d.Last().Code==YouTubeChatCode.Cancelled&&h.Requests.Count==2);SafeChat(d);});
Test("credential expiry before stream is distinguished from videos request",()=>{var h=new ApiHandler();h.Responses.Enqueue(JsonReply(LiveJson()));var provider=new SecondCredential();var d=new List<YouTubeChatDiagnostic>();using var s=new OfficialYouTubeChatSource(provider,new HttpClient(h),progress:d.Add);Deny(YouTubeFailure.AuthenticationExpired,()=>SourceRun(s).GetAwaiter().GetResult());Check(d.Last().Stage==YouTubeChatStage.Credential&&d.Last().Failure==YouTubeFailure.AuthenticationExpired&&h.Requests.Count==1&&provider.Calls==2);SafeChat(d);});
Test("throwing diagnostic sink cannot change request or failure",()=>{var h=new ApiHandler();h.Responses.Enqueue(JsonReply(LiveJson()));h.Responses.Enqueue(GrpcReply(Array.Empty<byte>(),"14"));using var s=new OfficialYouTubeChatSource(new MemoryYouTubeCredentials(Credential()),new HttpClient(h),progress:_=>throw new Exception(ChatPrivate));Deny(YouTubeFailure.NetworkInterrupted,()=>SourceRun(s).GetAwaiter().GetResult());Check(h.Requests.Count==2);});
foreach(var why in new[]{YouTubeFailure.PermissionDenied,YouTubeFailure.QuotaExceeded,YouTubeFailure.AuthenticationExpired,YouTubeFailure.LiveEnded})Test("terminal owner stop does not retry "+why,()=>{var old=YouTubeOfficialRuntime.Diagnostics;ResetStream();var q=new ConcurrentQueue<YouTubeChatDiagnostic>();YouTubeOfficialRuntime.Diagnostics=q.Enqueue;try{var(i,h)=FakeStream();h.Failure=why;TownOfHost.Main.ShowStreamComments.Value=true;StreamerInfo.CommentFrameTick(.02f);Check(SpinWait.SpinUntil(()=>h.Calls==1&&(int)typeof(StreamerInfo).GetField("fetching",flags).GetValue(null)==0,3000));Check(q.Last().Stage==YouTubeChatStage.Stop&&q.Last().Code==YouTubeChatCode.TerminalFailure&&q.Last().Attempt==1&&!q.Any(x=>x.Code==YouTubeChatCode.RetryScheduled));SafeChat(q);}finally{StreamerInfo.StopNetwork();WaitFetch();YouTubeOfficialRuntime.Diagnostics=old;}});
Test("cancel during retry wait reports cancellation and no second request",()=>{var old=YouTubeOfficialRuntime.Diagnostics;ResetStream();var q=new ConcurrentQueue<YouTubeChatDiagnostic>();YouTubeOfficialRuntime.Diagnostics=q.Enqueue;try{var(i,h)=FakeStream();h.Failure=YouTubeFailure.NetworkInterrupted;TownOfHost.Main.ShowStreamComments.Value=true;StreamerInfo.CommentFrameTick(.02f);Check(SpinWait.SpinUntil(()=>q.Any(x=>x.Code==YouTubeChatCode.RetryScheduled),3000));StreamerInfo.StopNetwork();WaitFetch();Check(h.Calls==1&&q.Last().Stage==YouTubeChatStage.Stop&&q.Last().Code==YouTubeChatCode.Cancelled);SafeChat(q);}finally{StreamerInfo.StopNetwork();WaitFetch();YouTubeOfficialRuntime.Diagnostics=old;}});
Test("four-attempt owner policy logs 5 10 20 seconds then stops",()=>{var old=YouTubeOfficialRuntime.Diagnostics;ResetStream();var q=new ConcurrentQueue<YouTubeChatDiagnostic>();YouTubeOfficialRuntime.Diagnostics=q.Enqueue;try{var(i,h)=FakeStream();h.Failure=YouTubeFailure.NetworkInterrupted;TownOfHost.Main.ShowStreamComments.Value=true;StreamerInfo.CommentFrameTick(.02f);Check(SpinWait.SpinUntil(()=>h.Calls==4&&(int)typeof(StreamerInfo).GetField("fetching",flags).GetValue(null)==0,45000));var retries=q.Where(x=>x.Code==YouTubeChatCode.RetryScheduled).ToArray();Check(retries.Select(x=>x.RetryDelaySeconds).SequenceEqual(new[]{5,10,20})&&retries.Select(x=>x.Attempt).SequenceEqual(new[]{1,2,3})&&q.Last().Stage==YouTubeChatStage.Stop&&q.Last().Code==YouTubeChatCode.RetryExhausted&&q.Last().Attempt==4);SafeChat(q);}finally{StreamerInfo.StopNetwork();WaitFetch();YouTubeOfficialRuntime.Diagnostics=old;}});
}
}
